{
  "application": "report-generation",
  "case_id": "case-fitness-tracker-health-metrics-en",
  "language": "en",
  "report": {
    "type": "analytics-report",
    "audience": "health-analytics-team",
    "tone": "analytical, data-forward, actionable"
  },
  "brief": {
    "title": "Fitness Tracker User Health & Activity Analytics Report",
    "one_liner": "A comprehensive analysis of daily health metrics, activity patterns, and lifestyle indicators across a synthetic cohort of fitness tracker users from 2015 to 2025.",
    "goal": "Enable the health analytics team to identify key activity and wellness patterns segmented by demographics, workout behavior, and lifestyle factors, and to surface actionable insights for product feature development and user engagement strategies."
  },
  "required_sections": [
    {
      "section_id": "demographic-overview",
      "title": "User Demographics & Body Metrics Overview",
      "objective": "Summarize the distribution of users by age, gender, height, and weight, highlighting key demographic segments in the dataset."
    },
    {
      "section_id": "activity-analysis",
      "title": "Physical Activity & Workout Patterns",
      "objective": "Analyze daily step counts, workout types, and workout durations to identify activity level distributions and preferences across user segments."
    },
    {
      "section_id": "health-vitals",
      "title": "Heart Rate, Sleep & Calorie Burn Analysis",
      "objective": "Examine average heart rate, sleep duration, and calories burned, exploring correlations and distributions across demographic and activity groups."
    },
    {
      "section_id": "lifestyle-wellness",
      "title": "Lifestyle & Wellness Indicators",
      "objective": "Assess water intake, stress levels, and mood distributions, and explore how these lifestyle factors relate to physical activity and health metrics."
    },
    {
      "section_id": "temporal-trends",
      "title": "Temporal Trends & Seasonal Patterns",
      "objective": "Investigate how key health and activity metrics evolve over time (yearly, monthly, or day-of-week), identifying any notable trends or seasonal effects."
    },
    {
      "section_id": "key-insights-recommendations",
      "title": "Key Insights & Recommendations",
      "objective": "Synthesize the most important findings from the analysis and provide data-driven recommendations for product and engagement strategies."
    }
  ],
  "kpis": [
    {
      "name": "Average Daily Steps",
      "description": "Mean number of steps taken per day across all users, segmented by key dimensions."
    },
    {
      "name": "Average Calories Burned",
      "description": "Mean daily calorie expenditure, analyzed by workout type and demographic group."
    },
    {
      "name": "Average Sleep Duration",
      "description": "Mean hours of sleep per night, with attention to variation across stress levels and mood categories."
    },
    {
      "name": "Workout Participation Rate",
      "description": "Percentage of daily records where a workout was performed (workout_type is not 'None')."
    },
    {
      "name": "Average Stress Level",
      "description": "Mean stress level score across the user base, segmented by activity level and mood."
    }
  ],
  "analysis_dimensions": [
    "gender",
    "workout_type",
    "mood",
    "stress_level",
    "date"
  ]
}

