[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fitness Tracker User Health &amp; Activity Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1e40af;
    --primary-light: #3b82f6;
    --accent: #0ea5e9;
    --accent2: #10b981;
    --accent3: #f59e0b;
    --accent4: #ef4444;
    --accent5: #8b5cf6;
    --bg: #f8fafc;
    --card: #ffffff;
    --border: #e2e8f0;
    --text: #0f172a;
    --text-muted: #64748b;
    --text-light: #94a3b8;
    --sidebar: #1e293b;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 14px;
  }

  /* LAYOUT */
  .layout { display: flex; min-height: 100vh; }

  .sidebar {
    width: 240px;
    background: var(--sidebar);
    position: fixed;
    top: 0; left: 0; bottom: 0;
    overflow-y: auto;
    z-index: 100;
    padding: 0 0 24px;
  }

  .sidebar-logo {
    padding: 20px 20px 16px;
    border-bottom: 1px solid rgba(255,255,255,0.08);
    margin-bottom: 8px;
  }

  .sidebar-logo .logo-icon {
    width: 32px; height: 32px;
    background: var(--primary-light);
    border-radius: 8px;
    display: inline-flex; align-items: center; justify-content: center;
    color: white; font-size: 16px; margin-bottom: 8px;
  }

  .sidebar-logo h2 { color: white; font-size: 13px; font-weight: 600; line-height: 1.3; }
  .sidebar-logo p { color: rgba(255,255,255,0.4); font-size: 11px; margin-top: 2px; }

  .sidebar nav a {
    display: flex; align-items: center; gap: 8px;
    color: rgba(255,255,255,0.55);
    text-decoration: none;
    padding: 8px 20px;
    font-size: 12.5px;
    transition: all 0.15s;
    border-left: 3px solid transparent;
  }

  .sidebar nav a:hover,
  .sidebar nav a.active {
    color: white;
    background: rgba(255,255,255,0.06);
    border-left-color: var(--primary-light);
  }

  .sidebar nav .nav-section {
    color: rgba(255,255,255,0.28);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 16px 20px 4px;
  }

  .main {
    margin-left: 240px;
    flex: 1;
    min-width: 0;
  }

  .page-header {
    background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 50%, #1d4ed8 100%);
    padding: 40px 40px 48px;
    color: white;
    position: relative;
    overflow: hidden;
  }

  .page-header::before {
    content: '';
    position: absolute; top: -40px; right: -40px;
    width: 200px; height: 200px;
    border-radius: 50%;
    background: rgba(255,255,255,0.05);
  }

  .page-header::after {
    content: '';
    position: absolute; bottom: -60px; right: 80px;
    width: 300px; height: 300px;
    border-radius: 50%;
    background: rgba(255,255,255,0.04);
  }

  .page-header .badge {
    display: inline-block;
    background: rgba(255,255,255,0.15);
    padding: 3px 10px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    margin-bottom: 12px;
    border: 1px solid rgba(255,255,255,0.2);
  }

  .page-header h1 { font-size: 26px; font-weight: 700; margin-bottom: 8px; line-height: 1.2; }
  .page-header p { color: rgba(255,255,255,0.75); font-size: 14px; max-width: 600px; }

  .header-meta {
    display: flex; gap: 24px; margin-top: 20px;
    flex-wrap: wrap;
  }

  .header-meta .meta-item {
    display: flex; align-items: center; gap: 6px;
    color: rgba(255,255,255,0.6);
    font-size: 12px;
  }

  .header-meta .meta-item strong { color: rgba(255,255,255,0.9); }

  .content { padding: 32px 40px; max-width: 1200px; }

  /* SECTIONS */
  .section { margin-bottom: 48px; }
  .section-header { margin-bottom: 20px; }

  .section-label {
    display: inline-block;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--primary-light);
    margin-bottom: 4px;
  }

  .section-header h2 {
    font-size: 20px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 4px;
  }

  .section-header p {
    color: var(--text-muted);
    font-size: 13px;
    max-width: 700px;
  }

  /* KPI CARDS */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 32px;
  }

  .kpi-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    position: relative;
    overflow: hidden;
    transition: box-shadow 0.2s;
  }

  .kpi-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.08); }

  .kpi-card .kpi-accent {
    position: absolute; top: 0; left: 0; right: 0;
    height: 3px;
    border-radius: 12px 12px 0 0;
  }

  .kpi-card .kpi-icon {
    width: 36px; height: 36px;
    border-radius: 8px;
    display: flex; align-items: center; justify-content: center;
    font-size: 18px;
    margin-bottom: 12px;
  }

  .kpi-card .kpi-value {
    font-size: 28px;
    font-weight: 800;
    color: var(--text);
    line-height: 1;
    margin-bottom: 4px;
  }

  .kpi-card .kpi-label {
    font-size: 12px;
    color: var(--text-muted);
    font-weight: 500;
  }

  .kpi-card .kpi-sub {
    font-size: 11px;
    color: var(--text-light);
    margin-top: 6px;
  }

  /* GRID LAYOUTS */
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 20px; }
  .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; margin-bottom: 20px; }
  .grid-2-1 { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; margin-bottom: 20px; }
  .grid-1-2 { display: grid; grid-template-columns: 1fr 2fr; gap: 20px; margin-bottom: 20px; }

  /* CHART CARDS */
  .chart-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    transition: box-shadow 0.2s;
  }

  .chart-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.06); }

  .chart-card h3 {
    font-size: 14px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 2px;
  }

  .chart-card .chart-sub {
    font-size: 11.5px;
    color: var(--text-muted);
    margin-bottom: 16px;
  }

  .chart-wrap { position: relative; }

  /* TABLES */
  .table-wrap { overflow-x: auto; }
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }

  thead th {
    background: #f1f5f9;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    padding: 10px 14px;
    text-align: left;
    border-bottom: 2px solid var(--border);
    white-space: nowrap;
  }

  tbody tr { border-bottom: 1px solid var(--border); }
  tbody tr:last-child { border-bottom: none; }
  tbody tr:hover { background: #f8fafc; }

  tbody td {
    padding: 10px 14px;
    color: var(--text);
  }

  tbody td.num { font-variant-numeric: tabular-nums; font-weight: 600; }
  tbody td.muted { color: var(--text-muted); font-size: 12px; }

  /* BADGES */
  .badge-pill {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 600;
  }

  .badge-blue { background: #dbeafe; color: #1d4ed8; }
  .badge-green { background: #dcfce7; color: #16a34a; }
  .badge-amber { background: #fef3c7; color: #b45309; }
  .badge-red { background: #fee2e2; color: #dc2626; }
  .badge-purple { background: #ede9fe; color: #7c3aed; }

  /* BAR INLINE */
  .bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
  .bar-label { width: 100px; font-size: 12px; color: var(--text-muted); text-align: right; flex-shrink: 0; }
  .bar-track { flex: 1; background: #f1f5f9; border-radius: 4px; height: 8px; overflow: hidden; }
  .bar-fill { height: 100%; border-radius: 4px; transition: width 0.5s; }
  .bar-val { width: 60px; font-size: 12px; font-weight: 600; color: var(--text); }

  /* INSIGHT CARDS */
  .insight-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; }

  .insight-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    display: flex; gap: 14px;
  }

  .insight-card .insight-icon {
    width: 40px; height: 40px; flex-shrink: 0;
    border-radius: 10px;
    display: flex; align-items: center; justify-content: center;
    font-size: 20px;
  }

  .insight-card h4 { font-size: 13.5px; font-weight: 700; margin-bottom: 4px; }
  .insight-card p { font-size: 12.5px; color: var(--text-muted); line-height: 1.5; }

  .insight-card .tag {
    display: inline-block;
    margin-top: 8px;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  /* PRIORITY CALLOUT */
  .callout {
    background: linear-gradient(135deg, #eff6ff, #f0fdf4);
    border: 1px solid #bfdbfe;
    border-left: 4px solid var(--primary-light);
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 20px;
    font-size: 13px;
    color: #1e3a8a;
  }

  .callout strong { font-weight: 700; }

  /* DIVIDER */
  .divider {
    border: none;
    border-top: 1px solid var(--border);
    margin: 32px 0;
  }

  /* STAT CHIPS */
  .stat-chips { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 8px; }
  .stat-chip {
    background: #f1f5f9;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 8px 14px;
    font-size: 12px;
  }

  .stat-chip .chip-val { font-size: 18px; font-weight: 800; display: block; color: var(--primary); }
  .stat-chip .chip-label { color: var(--text-muted); }

  /* FOOTER */
  .footer {
    background: var(--sidebar);
    color: rgba(255,255,255,0.4);
    text-align: center;
    padding: 20px 40px;
    font-size: 12px;
    margin-top: 48px;
  }

  /* RESPONSIVE */
  @media (max-width: 900px) {
    .sidebar { width: 200px; }
    .main { margin-left: 200px; }
    .grid-2, .grid-3, .grid-2-1, .grid-1-2 { grid-template-columns: 1fr; }
    .content { padding: 20px; }
    .page-header { padding: 24px; }
  }

  .highlight-number { color: var(--primary-light); font-weight: 800; }
  .full-width { grid-column: 1 / -1; }

  .trend-up { color: #16a34a; font-size: 11px; font-weight: 600; }
  .trend-down { color: #dc2626; font-size: 11px; font-weight: 600; }
  .trend-neutral { color: var(--text-muted); font-size: 11px; }
</style>
</head>
<body>

<!-- SIDEBAR -->
<div class="layout">
<nav class="sidebar">
  <div class="sidebar-logo">
    <div class="logo-icon">&#128200;</div>
    <h2>Health &amp; Activity Analytics</h2>
    <p>Fitness Tracker Cohort 2015–2025</p>
  </div>
  <div class="nav-section">Sections</div>
  <a href="#demographics">&#128101; Demographics</a>
  <a href="#activity">&#127939; Activity &amp; Workouts</a>
  <a href="#vitals">&#10084; Vitals &amp; Sleep</a>
  <a href="#lifestyle">&#127774; Lifestyle &amp; Wellness</a>
  <a href="#temporal">&#128197; Temporal Trends</a>
  <a href="#insights">&#128161; Key Insights</a>
</nav>

<!-- MAIN CONTENT -->
<div class="main">

<!-- PAGE HEADER -->
<div class="page-header">
  <div class="badge">Health Analytics Report</div>
  <h1>Fitness Tracker User Health &amp;<br>Activity Analytics Report</h1>
  <p>A comprehensive analysis of daily health metrics, activity patterns, and lifestyle indicators across a synthetic cohort of fitness tracker users from 2015 to 2025.</p>
  <div class="header-meta">
    <div class="meta-item">&#128197; <span><strong>Jan 2015 – Dec 2025</strong></span></div>
    <div class="meta-item">&#128101; <span><strong>970</strong> Unique Users</span></div>
    <div class="meta-item">&#128202; <span><strong>4,000</strong> Daily Records</span></div>
    <div class="meta-item">&#127942; <span>Audience: <strong>Health Analytics Team</strong></span></div>
    <div class="meta-item">&#128197; <span>Published: <strong>April 21, 2026</strong></span></div>
  </div>
</div>

<div class="content">

<!-- =========================================
     GLOBAL KPI DASHBOARD
     ========================================= -->
<div class="section">
  <div class="section-header">
    <span class="section-label">Global KPIs</span>
    <h2>Key Performance Indicators</h2>
    <p>Primary engagement and wellness metrics across all 4,000 daily records (970 unique users, 2015–2025).</p>
  </div>

  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-accent" style="background: linear-gradient(90deg, #3b82f6, #0ea5e9);"></div>
      <div class="kpi-icon" style="background:#eff6ff;">&#128694;</div>
      <div class="kpi-value">10,574</div>
      <div class="kpi-label">Avg Daily Steps</div>
      <div class="kpi-sub">Range: 1,003 – 19,993 &nbsp;|&nbsp; Median: 10,725</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-accent" style="background: linear-gradient(90deg, #10b981, #34d399);"></div>
      <div class="kpi-icon" style="background:#f0fdf4;">&#128293;</div>
      <div class="kpi-value">616.7</div>
      <div class="kpi-label">Avg Calories Burned</div>
      <div class="kpi-sub">Range: 120 – 900 &nbsp;|&nbsp; Median: 629.8</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-accent" style="background: linear-gradient(90deg, #8b5cf6, #a78bfa);"></div>
      <div class="kpi-icon" style="background:#f5f3ff;">&#128164;</div>
      <div class="kpi-value">6.99 h</div>
      <div class="kpi-label">Avg Sleep Duration</div>
      <div class="kpi-sub">Range: 3.0 – 10.0 h &nbsp;|&nbsp; Median: 7.0 h</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-accent" style="background: linear-gradient(90deg, #f59e0b, #fbbf24);"></div>
      <div class="kpi-icon" style="background:#fffbeb;">&#127947;</div>
      <div class="kpi-value">83.1%</div>
      <div class="kpi-label">Workout Participation Rate</div>
      <div class="kpi-sub">3,325 / 4,000 records with active workout</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-accent" style="background: linear-gradient(90deg, #ef4444, #f87171);"></div>
      <div class="kpi-icon" style="background:#fff1f2;">&#128161;</div>
      <div class="kpi-value">5.45</div>
      <div class="kpi-label">Avg Stress Level</div>
      <div class="kpi-sub">Scale 1–10 &nbsp;|&nbsp; Near-uniform distribution</div>
    </div>
  </div>
</div>

<hr class="divider">

<!-- =========================================
     SECTION 1: DEMOGRAPHICS
     ========================================= -->
<div class="section" id="demographics">
  <div class="section-header">
    <span class="section-label">Section 1</span>
    <h2>User Demographics &amp; Body Metrics Overview</h2>
    <p>Distribution of users by age, gender, height, and weight across the synthetic cohort.</p>
  </div>

  <div class="grid-2">
    <!-- Gender Split -->
    <div class="chart-card">
      <h3>Gender Distribution</h3>
      <div class="chart-sub">50.6% Male / 49.4% Female — near-equal split across 4,000 records</div>
      <div class="chart-wrap" style="height:220px;">
        <canvas id="genderChart"></canvas>
      </div>
    </div>

    <!-- Age Distribution -->
